async function c(){try{const s="koalastuff_github_repos";let o=null;const d=localStorage.getItem(s);if(d){const t=JSON.parse(d);Date.now()-t.timestamp<360*60*1e3&&(o=t.data)}if(!o){const t=await fetch("https://api.github.com/users/Shik3i/repos?sort=updated&per_page=100");if(!t.ok)return;o=await t.json(),localStorage.setItem(s,JSON.stringify({timestamp:Date.now(),data:o}))}const r=new Map;o.forEach(t=>{r.set(t.full_name.toLowerCase(),new Date(t.pushed_at||t.updated_at))}),document.querySelectorAll(".github-last-updated").forEach(t=>{const i=t.getAttribute("data-github-repo");if(!i)return;const n=r.get(i.toLowerCase());if(n){const e=Math.floor((Date.now()-n.getTime())/864e5);let a="";e===0?a="Updated today":e===1?a="Updated yesterday":e<30?a=`Updated ${e}d ago`:e<365?a=`Updated ${Math.floor(e/30)}mo ago`:a=`Updated ${Math.floor(e/365)}y ago`,t.innerHTML=`<span class="update-dot"></span>${a}`,t.classList.add("has-fresh-data")}})}catch(s){console.error("Failed to fetch github data",s)}}document.addEventListener("astro:page-load",c);
